unsigned char grid[DMAX][DMAX];

void floodFill(int x, int y) {
    const unsigned char value = grid[x][y];
    vector<uint32_t> pending;
    pending.push_back(static_cast<uint32_t>(x * DMAX + y));

    while (!pending.empty()) {
        uint32_t encoded = pending.back();
        pending.pop_back();

        int row = encoded / DMAX;
        int col = encoded % DMAX;

        if (grid[row][col] != value)
