struct line {
    double m, n;

    line(point A, point B) {
        m = (A.y - B.y) / (A.x - B.x);
        n = A.y - m * A.x;
    }

    line(point A, double _m) {
        m = _m;
        n = A.y - m * A.x;
    }

    line(double _m, double _n) : m(_m), n(_n) {}

    point intersect(const line &l) const {
        point O;
